content.text:
{
  "name": "HTTP REST连接适配器",
  "name_en": "HTTP REST Connection Adapter",
  "manufacturer": "",
  "description": "这不是特定的物理实验设备，而是一个通用的 HTTP/REST 通信连接组件，用于在实验室软件与提供 Web API 的仪器、控制器或自动化系统之间发送请求并接收响应。",
  "description_en": "This is not a specific physical lab device, but a generic HTTP/REST communication component used to send requests and receive responses between laboratory software and instruments, controllers, or automation systems that expose a web API.",
  "actions": [
    {
      "action_name": "auto-open_connection",
      "description": "打开并初始化 HTTP 会话连接。",
      "description_en": "Open and initialize the HTTP session."
    },
    {
      "action_name": "auto-close_connection",
      "description": "关闭 HTTP 会话连接。",
      "description_en": "Close the HTTP session."
    },
    {
      "action_name": "auto-transmit",
      "description": "向指定的 HTTP API 端点发送请求消息。",
      "description_en": "Send a request message to the specified HTTP API endpoint."
    },
    {
      "action_name": "auto-receive",
      "description": "接收并返回 HTTP 响应及其头信息。",
      "description_en": "Receive and return the HTTP response together with its headers."
    },
    {
      "action_name": "auto-is_connection_open",
      "description": "检查连接会话是否处于可用状态。",
      "description_en": "Check whether the connection session is available."
    }
  ],
  "tag_hints": [
    "HTTP REST API",
    "instrument communication",
    "network control",
    "remote laboratory integration",
    "web-based device interface"
  ]
}

